import{c as a,Q as i,j as s,m as t}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"ADR-063 — Web container: multi-stage Dockerfile, nginx serves adapter-static bundle","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-063.md","filePath":"adr/ADR-063.md"}'),n={name:"adr/ADR-063.md"};function o(d,e,r,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="adr-063-—-web-container-multi-stage-dockerfile-nginx-serves-adapter-static-bundle" tabindex="-1">ADR-063 — Web container: multi-stage Dockerfile, nginx serves <code>adapter-static</code> bundle <a class="header-anchor" href="#adr-063-—-web-container-multi-stage-dockerfile-nginx-serves-adapter-static-bundle" aria-label="Permalink to &quot;ADR-063 — Web container: multi-stage Dockerfile, nginx serves \`adapter-static\` bundle&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-22 Closes into · RFC-024 §4, §5 Related ADRs · ADR-005 (nginx + docker-compose · superseded by ADR-014, now partially revived for local stack), ADR-014 (GH Pages deploy), ADR-029 (PWA + service worker) Supersedes · none</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Orrery is published as a static SPA via <code>@sveltejs/adapter-static</code>. Today the only deploy path is GH Pages (per ADR-014). RFC-024 introduces a local docker-compose stack that wraps the same static bundle in an nginx container, so a contributor can <code>docker compose up -d web &amp;&amp; open http://localhost:8080</code> and exercise the production-shape artefact (gzipped, hash-asset-cached, no Vite dev server) without paying GH Pages deploy latency. The same image is what the new <code>docker-e2e.yml</code> CI workflow stands up to run Playwright against.</p><p>The decision is <em>how</em> to package this — one image vs many, what base, what stage layout, where the build runs, what nginx serves and how, and how this image relates to the eventual VPS deploy story (deferred to a separate RFC). Getting it wrong looks like: bloated images that ship <code>node_modules</code> at runtime; rebuild-on-every-data-change patterns; image-vs-volume seam confusion that makes pipeline refreshes invisible to the web tier.</p><p><code>ADR-005</code>&#39;s original &quot;nginx + docker-compose&quot; framing was retired when the project moved to a SvelteKit + GH Pages model (ADR-014). RFC-024 partially revives it — but as <em>local + CI infrastructure</em>, not as the production-deploy target. The VPS story is its own future RFC; this ADR is scoped to the local stack.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Ship a single multi-stage <code>Dockerfile</code> at the repo root. Stage 0 (<code>builder</code>) runs <code>npm ci &amp;&amp; npm run build</code> on <code>node:20-bookworm-slim</code>. Stage 1 (<code>web</code>) is <code>nginx:alpine</code>, copies <code>build/</code> from the builder, copies an <code>ops/docker/nginx.conf</code>, and exposes port 80. Stage 2 (<code>pipeline</code>) is covered by ADR-064. The compose file wires <code>web</code> to host port 8080 and mounts the <code>orrery-data</code> named volume read-only at <code>/usr/share/nginx/html/data</code>.</strong></p><h3 id="image-layout" tabindex="-1">Image layout <a class="header-anchor" href="#image-layout" aria-label="Permalink to &quot;Image layout&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx:alpine</span></span>
<span class="line"><span>└── /usr/share/nginx/html/</span></span>
<span class="line"><span>    ├── index.html</span></span>
<span class="line"><span>    ├── 404.html</span></span>
<span class="line"><span>    ├── _app/immutable/   ← hashed assets, immutable cache</span></span>
<span class="line"><span>    ├── data/             ← VOLUME MOUNT POINT (read-only)</span></span>
<span class="line"><span>    │   ├── launches.json</span></span>
<span class="line"><span>    │   ├── missions/*.json</span></span>
<span class="line"><span>    │   ├── i18n/*.json</span></span>
<span class="line"><span>    │   └── …             ← initially seeded from builder, then volume-overridden</span></span>
<span class="line"><span>    ├── manifest.webmanifest</span></span>
<span class="line"><span>    ├── sw.js</span></span>
<span class="line"><span>    └── …</span></span></code></pre></div><p>The image carries a <em>seed</em> of <code>static/data/</code> (whatever was in the repo at build time). On first <code>docker compose up</code>, the empty <code>orrery-data</code> volume is initialised from this seed (standard docker named-volume-on-first-mount behaviour, same mechanism postgres uses for <code>/var/lib/postgresql/data</code>). Subsequent pipeline writes update the volume contents in place; the seed copy in the image is masked.</p><h3 id="nginx-conf-shape" tabindex="-1"><code>nginx.conf</code> shape <a class="header-anchor" href="#nginx-conf-shape" aria-label="Permalink to &quot;\`nginx.conf\` shape&quot;">​</a></h3><p><code>ops/docker/nginx.conf</code> lives in the repo. Key directives:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  try_files </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$uri $uri/ /index.html;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># adapter-static SPA fallback</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /data/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cache-Control </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no-cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pipeline-refresh path; freshness matters</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Access-Control-Allow-Origin </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PWA SW already fetches with credentials=&#39;omit&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~*</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/_app/immutable/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cache-Control </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;public, max-age=31536000, immutable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">gzip </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">gzip_types </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">application/json application/javascript text/css text/html text/plain image/svg+xml;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">gzip_min_length </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The two key choices:</p><ol><li><strong><code>/data/*</code> is <code>no-cache</code>.</strong> Pipeline writes the volume; the next browser request must revalidate so refreshes propagate. The PWA SW&#39;s existing <code>NetworkFirst</code> strategy on <code>/data/**/*.json</code> (<code>vite.config.ts:90</code>) handles client-side caching; nginx just has to not lie about freshness.</li><li><strong><code>/_app/immutable/*</code> is <code>immutable</code>-cached for a year.</strong> Vite hashes every asset filename, so the URL itself encodes the version; aggressive caching is correct and matches GH Pages behaviour.</li></ol><h3 id="build-context-dockerignore" tabindex="-1">Build context + <code>.dockerignore</code> <a class="header-anchor" href="#build-context-dockerignore" aria-label="Permalink to &quot;Build context + \`.dockerignore\`&quot;">​</a></h3><p>Repo root <code>.dockerignore</code> excludes <code>node_modules</code>, <code>.svelte-kit</code>, <code>build</code>, <code>test-results</code>, <code>playwright-report</code>, <code>.image-cache</code>, <code>static/data</code> (we don&#39;t want the live data in the build context — the volume-mount on first run is the seeding mechanism, not the image bake; see §3 of the RFC for why). The exclude list keeps the build context under ~50 MB; without it, hotspots imagery + cache bloats it past 1 GB.</p><h3 id="stage-choice-node-20-bookworm-slim-builder-nginx-alpine-web" tabindex="-1">Stage choice (<code>node:20-bookworm-slim</code> builder, <code>nginx:alpine</code> web) <a class="header-anchor" href="#stage-choice-node-20-bookworm-slim-builder-nginx-alpine-web" aria-label="Permalink to &quot;Stage choice (\`node:20-bookworm-slim\` builder, \`nginx:alpine\` web)&quot;">​</a></h3><ul><li><strong>Builder</strong>: <code>node:20-bookworm-slim</code>. Node 20 matches the <code>.github/workflows/ci.yml</code> runner version (so CI and docker produce bit-identical <code>build/</code> output). Debian-bookworm-slim because glibc is the path of least resistance — alpine + musl breaks <code>gdal-async</code> and <code>sharp</code> install-from-source and we&#39;ve already lost hours to it elsewhere. Slim variant trims ~150 MB off the standard image.</li><li><strong>Web</strong>: <code>nginx:alpine</code>. 25 MB image, has no Node, no glibc dependencies, no userland complexity. Right tool for &quot;serve a static bundle on port 80.&quot; We accept that web and pipeline use different base distros (alpine vs debian); it&#39;s <em>not</em> a code-sharing problem because web runs no Node code.</li></ul><h3 id="healthcheck" tabindex="-1">Healthcheck <a class="header-anchor" href="#healthcheck" aria-label="Permalink to &quot;Healthcheck&quot;">​</a></h3><p><code>HEALTHCHECK CMD wget -qO- http://127.0.0.1/ &gt;/dev/null || exit 1</code> — alpine images have wget by default (not curl). 30s interval. Lets <code>docker compose ps</code> and CI&#39;s <code>until curl …; do sleep 2; done</code> block converge cleanly.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><p>A single multi-stage Dockerfile (rather than two separate Dockerfiles) shares the <code>builder</code> stage between web + pipeline images — <code>npm ci</code> happens once, layer cache is shared, image build time is roughly half what two independent Dockerfiles would cost.</p><p>Nginx-serves-static rather than <code>vite preview</code>-in-a-container because: (a) <code>vite preview</code> is <em>not</em> a production server — its own docs say so; (b) <code>vite preview</code> doesn&#39;t honour our <code>Cache-Control</code> policies for <code>_app/immutable</code>; (c) nginx is what every realistic VPS deploy will use anyway, so testing locally + in CI against nginx surfaces real production behaviour. Using <code>vite preview</code> would deliver test results that don&#39;t generalise.</p><p>Read-only mount on the web side is defence-in-depth: the web container shouldn&#39;t write to the data volume even by accident. Pipeline-runner has read-write access to the same volume.</p><p>Volume-overrides-seed is the only mechanism that lets fresh deploys (empty volume) self-bootstrap with whatever data was committed at build time, then <em>stay</em> fresh as pipeline refreshes layer on top. The alternative (always-empty volume + run pipeline before first useful render) introduces a chicken-and-egg state where the first request after deploy 404s on every <code>/data/*.json</code>.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Caddy instead of nginx for the web container.</strong> Caddy is friendlier (automatic HTTPS, declarative Caddyfile) but its strengths only matter when TLS + auto-cert are in scope, which they aren&#39;t for local + CI. Nginx is the dominant choice for static-bundle serving in production VPS deployments and matches what the future VPS RFC will likely also pick — using it here means we test what we&#39;ll deploy. Reconsider for the VPS RFC if TLS-handling pushes toward Caddy.</li><li><strong><code>vite preview</code> in a node container.</strong> Rejected. Not a production server. Doesn&#39;t honour cache-control policy. Adds a Node runtime to the web tier for no benefit.</li><li><strong>Distroless nginx (<code>gcr.io/distroless/static-debian12</code> with a sidecar serving binary).</strong> More secure (no shell, no package manager). Premature for local + CI; revisit in the production-hardening pass under §10 of RFC-024.</li><li><strong>Single-stage Dockerfile that builds everything in one image.</strong> Bloats the runtime image with <code>node_modules</code> + the entire builder toolchain (~1 GB for nothing). Multi-stage is the standard pattern; this isn&#39;t a case where the standard pattern is wrong.</li><li><strong>Don&#39;t bake a <code>static/data/</code> seed into the image; require operators to run pipelines before first use.</strong> Rejected for the chicken-and-egg reason above. The seed in the image is <em>the same data that&#39;s in the repo at build time</em> — it&#39;s not a privacy/secrecy issue, and it&#39;s the same data GH Pages already serves.</li><li><strong>Use <code>adapter-node</code> instead of <code>adapter-static</code> for the docker stack.</strong> Would add an SSR Node runtime to the web container, opens up routes/server endpoints. Out of scope — Orrery is a static app today and there&#39;s no driver to change that. Adding adapter-node would also break the GH Pages publish path (no Node runtime there).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Production-shape artefact reachable locally in one command (<code>npm run docker:up</code>).</li><li>CI can stand up the same image in <code>docker-e2e.yml</code> and exercise it with the existing Playwright suite — closes a known gap where <code>vite preview</code> doesn&#39;t exhibit production nginx behaviour.</li><li>The image is small (~25 MB nginx + the static bundle, ~30-50 MB total depending on data volume) and starts in &lt; 1 second.</li><li>Forward-compatible with the future VPS RFC: the same image is what gets pushed to GHCR; only the compose file diverges (TLS proxy override, etc.).</li></ul><p><strong>Negative:</strong></p><ul><li>One more thing to maintain — Dockerfile, nginx.conf, .dockerignore, the npm script wrappers. Roughly +100 LOC of ops surface.</li><li>Image rebuild on every code change (no live-reload through the container). For active dev, <code>npm run dev</code> is still the canonical loop; the docker stack is for &quot;test the production artefact&quot; + CI.</li><li>Bumping Node 20 → 22 (or nginx → next major) requires synchronising the Dockerfile, the GH Actions runner versions, and the e2e baseline. Tracked as routine maintenance, not a blocker.</li></ul><h2 id="decision-status" tabindex="-1">Decision status <a class="header-anchor" href="#decision-status" aria-label="Permalink to &quot;Decision status&quot;">​</a></h2><p><strong>Accepted on 2026-05-22.</strong> Shipped in commit <code>4789855ee</code> (Slice 1 of RFC-024) — but with one deliberate divergence from the original Draft: the web tier does NOT use a custom Dockerfile. It runs stock <code>nginx:alpine</code> with three read-only bind-mounts (<code>./build</code>, <code>./static/data</code>, <code>./ops/docker/nginx.conf</code>). The multi-stage Dockerfile that originally also built the web image was abandoned because rebuilding the SvelteKit bundle inside a linux/arm64 Docker VM on Apple Silicon triggered ~30 min of native-module compilation (gdal-async, sharp, canvas) for an artefact the host&#39;s <code>npm run build</code> already produces in 1-2 min. The bind-mount approach delivers the same nginx-serving contract — same <code>nginx.conf</code>, same cache headers, same SPA fallback — at zero build cost. See the <strong>Amendment — 2026-05-22</strong> section below.</p><h2 id="amendment-—-2026-05-22-during-slice-1-implementation-web-container-drops-its-dockerfile" tabindex="-1">Amendment — 2026-05-22 (during Slice 1 implementation): web container drops its Dockerfile <a class="header-anchor" href="#amendment-—-2026-05-22-during-slice-1-implementation-web-container-drops-its-dockerfile" aria-label="Permalink to &quot;Amendment — 2026-05-22 (during Slice 1 implementation): web container drops its Dockerfile&quot;">​</a></h2><p>The Draft prescribed a multi-stage Dockerfile with a <code>web</code> target that copied <code>build/</code> from a <code>builder</code> stage. First attempt to build that image on the implementer&#39;s machine (Apple Silicon, Docker Desktop) revealed two compounding problems:</p><ul><li><strong>Build context bloat (3.48 GB).</strong> The original <code>.dockerignore</code> missed <code>.linux-node-modules</code> (parallel-agent linux-binary cache, 429 MB), <code>.xdg-cache</code> (1 GB), and <code>.xdg-data</code> (1.3 GB — argos-translate models from the retired wave23 toolchain). BuildKit&#39;s context transfer alone took 165 seconds. Fixed by extending <code>.dockerignore</code>.</li><li><strong>Native-module compile inside linux/arm64 VM (~30 min and counting).</strong> Even with the slim context, the <code>builder</code> stage&#39;s <code>npm ci</code> triggered <code>gdal-async</code> + <code>sharp</code> + <code>canvas</code> to compile against system libs inside the Linux VM. That was wasted work — the host&#39;s <code>npm run build</code> already runs <code>vite build</code> in ~1-2 min, and none of those native modules are needed for SvelteKit&#39;s adapter-static build (they&#39;re scripts-only deps).</li></ul><p>The fix is structural, not tuning: <strong>the web container doesn&#39;t need a build step at all</strong>. nginx&#39;s job is to serve files; the files already exist on the host after <code>npm run build</code>. So the <code>docker-compose.yml</code> was changed to:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nginx:alpine</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./build:/usr/share/nginx/html:ro</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./static/data:/usr/share/nginx/html/data:ro</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./ops/docker/nginx.conf:/etc/nginx/conf.d/default.conf:ro</span></span></code></pre></div><p>No custom Dockerfile for web. Pulling <code>nginx:alpine</code> (25 MB) is a one-time 5-second download; subsequent <code>docker compose up -d web</code> invocations start in under a second. The repo-root <code>Dockerfile</code> is reduced to the pipeline-runner only (ADR-064).</p><p><strong>Trade-off — the web stack now requires <code>npm run build</code> to be run on the host before <code>docker compose up -d web</code>.</strong> That mirrors what operators already do for GH Pages (same <code>npm run build</code>), so it&#39;s not new cognitive load — but it is one more step compared to &quot;everything inside docker compose.&quot; The Dockerfile-builds-the-bundle approach we abandoned would have been self-contained but is fundamentally the wrong tool for an Apple Silicon dev host. When the future VPS RFC materialises, the prod image will bake the bundle in (built either on the VPS or in CI), at which point the local-dev bind-mount and the prod baked-in artefact diverge cleanly. The contract this ADR documents — <em>nginx serves the adapter-static bundle with the cache-header + SPA-fallback policy in <code>ops/docker/nginx.conf</code></em> — holds either way.</p><p>The <code>nginx.conf</code> itself acquired three small adjustments during Slice 1:</p><ol><li><code>try_files $uri $uri.html $uri/index.html /index.html</code> (instead of the original <code>$uri $uri/</code>) — adapter-static emits <code>build/missions.html</code> (file at root) rather than <code>build/missions/index.html</code>, so the bare <code>$uri/</code> fallback hit a 403 on the directory.</li><li><code>include /etc/nginx/mime.types;</code> before the custom <code>types { application/manifest+json webmanifest; }</code> block — a bare <code>types {}</code> block <strong>replaces</strong> the default mime mappings (a known nginx footgun), which clobbered <code>application/json</code> for <code>.json</code> files.</li><li><code>Cache-Control: no-cache</code> is set on <code>/data/</code>, <code>/sw.js</code>, and <code>/manifest.webmanifest</code>; <code>public, max-age=31536000, immutable</code> is set on <code>/_app/immutable/*</code>.</li></ol><p>All three landed in <code>ops/docker/nginx.conf</code> in the same Slice 1 commit. None change this ADR&#39;s overall contract; they&#39;re implementation details that this Amendment records so future maintainers see &quot;yes, we considered the directory-vs-file thing.&quot;</p>`,46)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
